mapper.select:
select cusip || '|' || securityid || '|' || securityname from Issue_Info where 1=1

	and sourceID.sourceID=#{sourceid}


	and issueType=#{secType}

 order by securityid asc

choose.when:
select issueinfo0_.CUSIP as CUSIP, interfaces3_.sourceDesc as sourcename, rpsectype4_.typename as secType, issueinfo0_.SECURITYID as secCode, '-' as secName, '-' as industryName, coaagroup1_.groupName as coaName, fxcurrency2_.CURR_CODE as curName, '-' as country from ISSUE_INFO issueinfo0_, InterfaceSource interfaces3_, RPSecType rpsectype4_ cross join CoaaGroup coaagroup1_ cross join FX_CURRENCY fxcurrency2_ where issueinfo0_.sourceID=interfaces3_.sourceID and issueinfo0_.rpSecType=rpsectype4_.id and issueinfo0_.GLGROUP=coaagroup1_.groupNum and issueinfo0_.PriCur=fxcurrency2_.CURR_ID and issueinfo0_.issueType=#{secType} and issueinfo0_.sourceID in
#{item}
and issueinfo0_.securityid=#{secID}
order by securityid asc, fxcurrency2_.CURR_CODE asc

choose.otherwise:
select issueinfo0_.CUSIP as CUSIP, interfaces3_.sourceDesc as sourcename, rpsectype4_.typename as secType, issueinfo0_.SECURITYID as secCode, issueinfo0_.securityname as secName, rpsectype6_.typename as industryName, coaagroup1_.groupName as coaName, fxcurrency2_.CURR_CODE as curName, country8_.countryCode as country from ISSUE_INFO issueinfo0_, InterfaceSource interfaces3_, RPSecType rpsectype4_, ISSUER issuer5_, RPSecType rpsectype6_, Country country8_ cross join CoaaGroup coaagroup1_ cross join FX_CURRENCY fxcurrency2_ where issueinfo0_.sourceID=interfaces3_.sourceID and issueinfo0_.rpSecType=rpsectype4_.id and issueinfo0_.issuer=issuer5_.issuerID and issuer5_.rpSecType=rpsectype6_.id and issuer5_.country=country8_.countryID and issueinfo0_.GLGROUP=coaagroup1_.groupNum and issueinfo0_.PriCur=fxcurrency2_.CURR_ID and issueinfo0_.issueType=#{secType} and issueinfo0_.sourceID in
#{item}
and issueinfo0_.securityid=#{secID}
order by securityid asc, fxcurrency2_.CURR_CODE asc
